#include "track.h"
#include "rmath_random.h"


void cRTrack::Change(int texture_set)
{
    int selected;

    switch (texture_set) {
    case 0:
        selected = 0;
        break;
    case 1:
        selected = 1;
        break;
    case 2:
        selected = 2;
        break;
    case 3:
        selected = 3;
        break;
    case 5:
        selected = (int)RAND(4.0f, 0);
        break;
    default:
        selected = texture_set;
        break;
    }

    int previous = current_texture_set;
    if (selected != previous) {
        g_object_list.ReTextureObjects(
            track_textures[selected], track_textures[previous]);
        g_object_list.ReTextureObjects(
            slide_textures[selected], slide_textures[current_texture_set]);
        current_texture_set = selected;
    }
}

